{"schema_version":1,"summary":"Selected a tenant-scoped shadow copy and compare-and-swap cutover with checkpointed copying, verification, and a 30-second write-pause limit.","changes":[{"path":"decision.json","content":"{
  "schema_version": 1,
  "selected_strategy": "shadow-copy-cas",
  "rationale": "Use the existing copy worker, router, and stores to migrate tenants independently. Keep the legacy store as each tenant's sole live writer until its atomic route change. Copy idempotently from a durable per-tenant checkpoint and verify ordered event identity and content. Pause only the tenant being cut over, then capture its final legacy watermark, copy and verify the delta, and change the route only if the expected legacy route version and final watermark still match and verification passed. If the gate fails or the 30-second pause budget would be exceeded before cutover, resume legacy writes and reuse the checkpoint. After cutover, the new store is the sole authority; repair it forward while retaining legacy data as evidence.",
  "constraints_addressed": ["C1", "C2", "C3", "C4", "C5", "C6", "C7"],
  "rejected_strategies": {
    "global-stop-rewrite": "Violates C1 by stopping writes globally.",
    "dual-write-backfill": "Violates C2 by writing to both stores before the tenant's atomic route change.",
    "cdc-mirror-cutover": "Violates C6 by introducing a CDC pipeline and lag monitor, and C2 by mirroring writes before the route change."
  },
  "plan": [
    {
      "step_id": "p1",
      "operation": "capture_initial_watermark",
      "depends_on": [],
      "satisfies": ["C3", "C7"]
    },
    {
      "step_id": "p2",
      "operation": "shadow_copy",
      "depends_on": ["p1"],
      "satisfies": ["C3", "C6", "C7"]
    },
    {
      "step_id": "p3",
      "operation": "verify_shadow",
      "depends_on": ["p2"],
      "satisfies": ["C4"]
    },
    {
      "step_id": "p4",
      "operation": "freeze_tenant_writes",
      "depends_on": ["p3"],
      "satisfies": ["C1", "C2", "C7"]
    },
    {
      "step_id": "p5",
      "operation": "capture_final_watermark",
      "depends_on": ["p4"],
      "satisfies": ["C4"]
    },
    {
      "step_id": "p6",
      "operation": "copy_delta",
      "depends_on": ["p5"],
      "satisfies": ["C3", "C4"]
    },
    {
      "step_id": "p7",
      "operation": "verify_final",
      "depends_on": ["p6"],
      "satisfies": ["C4"]
    },
    {
      "step_id": "p8",
      "operation": "cas_route",
      "depends_on": ["p7"],
      "satisfies": ["C2", "C4", "C5"]
    },
    {
      "step_id": "p9",
      "operation": "unfreeze_tenant_writes",
      "depends_on": ["p8"],
      "satisfies": ["C1", "C5", "C7"]
    },
    {
      "step_id": "p10",
      "operation": "monitor",
      "depends_on": ["p9"],
      "satisfies": ["C5", "C6", "C7"]
    }
  ],
  "cutover_gate": {
    "mode": "compare_and_swap",
    "requires": ["legacy_route_version", "final_watermark", "verification_passed"]
  },
  "rollback": {
    "before_cutover": "resume_legacy_and_reuse_checkpoint",
    "after_cutover": "forward_repair_on_new_store"
  },
  "max_tenant_write_pause_seconds": 30
}
"}],"test_plan":["python -m pytest -q"]}
